/**
 * San.Lab — Validation.gs
 * Ошибки, проверки, утилиты дат и чисел. Общий файл ядра.
 */

function AppError(code, message, details) {
  this.name = 'AppError';
  this.code = code;
  this.message = message;
  this.details = details || null;
}
AppError.prototype = Object.create(Error.prototype);
AppError.prototype.constructor = AppError;

function fail(code, message, details) { throw new AppError(code, message, details); }
function denied(message) { throw new AppError('ACCESS_DENIED', message || 'Нет доступа к этой записи или действию'); }
function notFound(what) { throw new AppError('NOT_FOUND', (what ? what + ': з' : 'З') + 'апись не найдена или нет доступа'); }

var V = {
  str: function (v) { return v === null || v === undefined ? '' : String(v).replace(/^\s+|\s+$/g, ''); },
  isEmpty: function (v) { return v === null || v === undefined || (typeof v === 'string' && V.str(v) === ''); },
  required: function (obj, fields, labels) {
    var missing = [];
    for (var i = 0; i < fields.length; i++) {
      if (V.isEmpty(obj[fields[i]])) missing.push((labels && labels[fields[i]]) || fields[i]);
    }
    if (missing.length) fail('VALIDATION', 'Заполните обязательные поля: ' + missing.join(', '), { missing: missing });
  },
  oneOf: function (value, dict, label) {
    if (!dict.hasOwnProperty(value)) fail('VALIDATION', 'Недопустимое значение поля «' + label + '»: ' + value);
  },
  num: function (v, label, opts) {
    var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.').replace(/\s/g, ''));
    if (isNaN(n)) fail('VALIDATION', 'Поле «' + label + '» должно быть числом');
    if (opts && opts.positive && n <= 0) fail('VALIDATION', 'Поле «' + label + '» должно быть больше нуля');
    if (opts && opts.nonNegative && n < 0) fail('VALIDATION', 'Поле «' + label + '» не может быть отрицательным');
    return Math.round(n * 100) / 100;
  },
  date: function (v, label) {
    if (V.isEmpty(v)) fail('VALIDATION', 'Укажите «' + label + '»');
    var d = new Date(v);
    if (isNaN(d.getTime())) fail('VALIDATION', 'Неверная дата в поле «' + label + '»');
    return d.toISOString();
  },
  inn: function (v) {
    var s = V.str(v);
    if (s && !/^(\d{10}|\d{12})$/.test(s)) fail('VALIDATION', 'ИНН должен содержать 10 или 12 цифр');
    return s;
  },
  email: function (v) {
    var s = V.str(v).toLowerCase();
    if (s && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s)) fail('VALIDATION', 'Неверный формат e-mail');
    return s;
  },
  bool: function (v) { return v === true || v === 'true' || v === 'TRUE' || v === 1 || v === '1' || v === 'да'; }
};

/* ---------- Даты (ISO-строки в ядре) ---------- */
var DAY_MS = 86400000;
function isoAddDays(iso, days) { return new Date(new Date(iso).getTime() + days * DAY_MS).toISOString(); }
function isoAddHours(iso, h) { return new Date(new Date(iso).getTime() + h * 3600000).toISOString(); }
function isBefore(a, b) { return new Date(a).getTime() < new Date(b).getTime(); }

/* Сдвиг часового пояса для группировки по дням (минуты), берётся из TZ-настройки при наличии */
var TZ_OFFSET_MIN = 300; // Asia/Yekaterinburg, Оренбург (UTC+5)
function localDayKey(iso) {
  if (!iso) return '';
  var d = new Date(new Date(iso).getTime() + TZ_OFFSET_MIN * 60000);
  return d.toISOString().slice(0, 10);
}
function pad2(n) { return (n < 10 ? '0' : '') + n; }
function fmtDT(iso) {
  if (!iso) return '—';
  var d = new Date(new Date(iso).getTime() + TZ_OFFSET_MIN * 60000);
  return pad2(d.getUTCDate()) + '.' + pad2(d.getUTCMonth() + 1) + '.' + d.getUTCFullYear() + ' ' + pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes());
}
function fmtD(iso) { return iso ? fmtDT(iso).slice(0, 10) : '—'; }
function fmtMoney(n) {
  var v = Math.round((Number(n) || 0) * 100) / 100;
  var parts = v.toFixed(2).split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  return (parts[1] === '00' ? parts[0] : parts.join(',')) + ' ₽';
}

/* ---------- Коллекции ---------- */
function indexBy(arr, key) { var m = {}; for (var i = 0; i < arr.length; i++) m[arr[i][key]] = arr[i]; return m; }
function groupBy(arr, key) { var m = {}; for (var i = 0; i < arr.length; i++) { var k = arr[i][key]; (m[k] = m[k] || []).push(arr[i]); } return m; }
function filterBy(arr, fn) { var out = []; for (var i = 0; i < arr.length; i++) if (fn(arr[i])) out.push(arr[i]); return out; }
function pick(obj, keys) { var o = {}; for (var i = 0; i < keys.length; i++) if (obj.hasOwnProperty(keys[i])) o[keys[i]] = obj[keys[i]]; return o; }
function sumBy(arr, key) { var s = 0; for (var i = 0; i < arr.length; i++) s += Number(arr[i][key]) || 0; return Math.round(s * 100) / 100; }
function sortBy(arr, key, desc) {
  return arr.slice().sort(function (a, b) {
    var x = a[key] || '', y = b[key] || '';
    if (x < y) return desc ? 1 : -1;
    if (x > y) return desc ? -1 : 1;
    return 0;
  });
}
function csvList(s) { return V.str(s) ? V.str(s).split(/\s*,\s*/) : []; }
function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
function safeJson(s, fallback) { try { return JSON.parse(s); } catch (e) { return fallback; } }
function shortJson(obj) {
  if (obj === null || obj === undefined) return '';
  var s = JSON.stringify(obj);
  return s.length > 4000 ? s.slice(0, 4000) + '…' : s;
}
/* Поля, которые никогда не пишутся в аудит и не уходят клиенту */
var SECRET_FIELDS = ['pin_hash', 'snapshot_json'];
function stripSecrets(obj) {
  if (!obj) return obj;
  var o = {};
  for (var k in obj) if (obj.hasOwnProperty(k) && SECRET_FIELDS.indexOf(k) < 0) o[k] = obj[k];
  return o;
}
function diffObj(oldO, newO) {
  var a = {}, b = {};
  for (var k in newO) {
    if (!newO.hasOwnProperty(k) || SECRET_FIELDS.indexOf(k) >= 0 || k === 'updated_at' || k === 'row_version') continue;
    var ov = oldO ? oldO[k] : undefined;
    if (String(ov === undefined || ov === null ? '' : ov) !== String(newO[k] === null || newO[k] === undefined ? '' : newO[k])) { a[k] = ov; b[k] = newO[k]; }
  }
  return { oldV: a, newV: b };
}

/**
 * San.Lab — Repository.gs
 * Тонкий слой над хранилищем (Store): ID, служебные поля, версии строк, настройки.
 * Store реализуется платформой: SheetsStore (Apps Script) или MemoryStore (демо/тесты).
 *   Store.all(table) / Store.get(table,id) / Store.insert(table,obj) / Store.update(table,id,patch) / Store.nextSeq(prefix)
 */

var Repo = {
  key: function (table) { return SCHEMA[table][0]; },

  newId: function (table) {
    var prefix = ID_PREFIX[table];
    var n = Store.nextSeq(prefix);
    var s = String(n);
    while (s.length < 6) s = '0' + s;
    return prefix + '-' + s;
  },

  all: function (table) { return Store.all(table); },
  get: function (table, id) { return id ? Store.get(table, id) : null; },
  must: function (table, id, label) {
    var r = Repo.get(table, id);
    if (!r) notFound(label || TABLE_LABELS[table]);
    return r;
  },
  where: function (table, fn) { return filterBy(Store.all(table), fn); },

  create: function (ctx, table, obj, opts) {
    var cols = SCHEMA[table];
    var key = cols[0];
    var row = {};
    for (var i = 0; i < cols.length; i++) row[cols[i]] = obj.hasOwnProperty(cols[i]) ? obj[cols[i]] : '';
    if (!row[key]) row[key] = Repo.newId(table);
    if (cols.indexOf('created_at') >= 0 && !row.created_at) row.created_at = ctx.now;
    if (cols.indexOf('created_by') >= 0 && !row.created_by) row.created_by = ctx.actorId;
    if (cols.indexOf('updated_at') >= 0) row.updated_at = ctx.now;
    if (cols.indexOf('updated_by') >= 0) row.updated_by = ctx.actorId;
    if (cols.indexOf('record_status') >= 0 && !row.record_status) row.record_status = 'ACTIVE';
    if (cols.indexOf('row_version') >= 0) row.row_version = 1;
    Store.insert(table, row);
    if (!(opts && opts.noAudit)) Audit.log(ctx, (opts && opts.action) || 'CREATE', table, row[key], null, stripSecrets(row));
    return row;
  },

  /* expectedVersion — защита от одновременной правки (row_version) */
  update: function (ctx, table, id, patch, opts) {
    var cur = Repo.must(table, id);
    if (opts && opts.expectedVersion && cur.row_version && Number(opts.expectedVersion) !== Number(cur.row_version)) {
      fail('CONFLICT', 'Запись изменена другим пользователем. Обновите карточку и повторите.');
    }
    var cols = SCHEMA[table];
    var clean = {};
    for (var k in patch) if (patch.hasOwnProperty(k) && cols.indexOf(k) >= 0 && k !== cols[0]) clean[k] = patch[k];
    if (cols.indexOf('updated_at') >= 0) clean.updated_at = ctx.now;
    if (cols.indexOf('updated_by') >= 0) clean.updated_by = ctx.actorId;
    if (cols.indexOf('row_version') >= 0) clean.row_version = (Number(cur.row_version) || 0) + 1;
    var d = diffObj(cur, clean);
    var updated = Store.update(table, id, clean);
    if (!(opts && opts.noAudit)) Audit.log(ctx, (opts && opts.action) || 'UPDATE', table, id, d.oldV, d.newV);
    return updated;
  }
};

/* ---------- Настройки ---------- */
var Settings = {
  _cache: null,
  load: function () {
    if (Settings._cache) return Settings._cache;
    var m = {};
    for (var k in SETTINGS_DEFAULTS) if (SETTINGS_DEFAULTS.hasOwnProperty(k)) m[k] = SETTINGS_DEFAULTS[k][0];
    var rows = Store.all('Settings');
    for (var i = 0; i < rows.length; i++) m[rows[i].setting_key] = String(rows[i].value === null || rows[i].value === undefined ? '' : rows[i].value);
    Settings._cache = m;
    return m;
  },
  reset: function () { Settings._cache = null; },
  get: function (key) { return Settings.load()[key]; },
  bool: function (key) { return V.bool(Settings.get(key)); },
  num: function (key) { return Number(Settings.get(key)) || 0; },
  json: function (key) { return safeJson(Settings.get(key), {}); },

  save: function (ctx, p) {
    var values = p.values || {};
    var changed = [];
    for (var key in values) {
      if (!values.hasOwnProperty(key)) continue;
      if (!SETTINGS_DEFAULTS.hasOwnProperty(key)) fail('VALIDATION', 'Неизвестная настройка: ' + key);
      var v = String(values[key]);
      if (/_JSON$|^TASK_DUE_DAYS$|^LAB_DUE_DAYS$/.test(key) && safeJson(v, null) === null) fail('VALIDATION', 'Настройка ' + key + ' должна быть в формате JSON');
      var existing = Store.get('Settings', key);
      var old = existing ? existing.value : SETTINGS_DEFAULTS[key][0];
      if (String(old) === v) continue;
      if (existing) Store.update('Settings', key, { value: v, updated_by: ctx.actorId, updated_at: ctx.now });
      else Store.insert('Settings', { setting_key: key, value: v, description: SETTINGS_DEFAULTS[key][1], updated_by: ctx.actorId, updated_at: ctx.now });
      Audit.log(ctx, 'SETTING_CHANGE', 'Settings', key, { value: old }, { value: v });
      changed.push(key);
    }
    Settings.reset();
    return { changed: changed };
  },

  list: function () {
    var m = Settings.load(), out = [];
    for (var k in SETTINGS_DEFAULTS) if (SETTINGS_DEFAULTS.hasOwnProperty(k)) out.push({ key: k, value: m[k], description: SETTINGS_DEFAULTS[k][1] });
    return out;
  }
};

/**
 * San.Lab — AuthService.gs + AuditService
 * Идентификация, роли, права на действие и на конкретную запись, журнал аудита.
 * Принцип: скрытая кнопка — не защита. Каждый вызов API проходит Auth.check на сервере.
 */

var Auth = {
  /* Определить сотрудника по сессии. Integr.currentEmail(token) реализуется платформой. */
  resolve: function (token) {
    var email = V.str(Integr.currentEmail(token, Settings.get('AUTH_MODE'))).toLowerCase();
    if (!email) fail('AUTH_REQUIRED', 'Требуется вход в систему');
    var emp = Auth.byEmail(email);
    if (!emp) fail('ACCESS_DENIED', 'Учётная запись ' + email + ' не зарегистрирована в San.Lab. Обратитесь к администратору.');
    if (!V.bool(emp.active)) fail('ACCOUNT_DISABLED', 'Учётная запись отключена. Новые действия запрещены.');
    return emp;
  },

  byEmail: function (email) {
    var list = Store.all('Employees');
    for (var i = 0; i < list.length; i++) if (V.str(list[i].email).toLowerCase() === email) return list[i];
    return null;
  },

  extraActions: function (user) {
    var out = [], ex = csvList(user.extra_perms);
    for (var i = 0; i < ex.length; i++) if (EXTRA_PERMS[ex[i]]) out = out.concat(EXTRA_PERMS[ex[i]]);
    if (user.role === 'COORDINATOR' && Settings.bool('COORDINATOR_FINANCE_ACCESS')) out = out.concat(EXTRA_PERMS.finance);
    return out;
  },

  can: function (user, action) {
    var roles = PERMS[action];
    if (!roles) return false;
    if (roles.indexOf('*') >= 0 || roles.indexOf(user.role) >= 0) return true;
    return Auth.extraActions(user).indexOf(action) >= 0;
  },

  check: function (user, action) {
    if (!Auth.can(user, action)) denied('Недостаточно прав для действия «' + action + '»');
  },

  isAdminLike: function (user) { return user.role === 'OWNER' || user.role === 'COORDINATOR'; },

  /* ---------- Доступ к выезду ---------- */
  canSeeVisit: function (user, v) {
    if (!v) return false;
    if (Auth.isAdminLike(user)) return true;
    if (user.role === 'SPECIALIST') return v.employee_id === user.employee_id;
    if (user.role === 'QC' || Auth.extraActions(user).indexOf('reports.approve') >= 0) {
      if (v.report_id || ['IN_REVIEW', 'RETURNED', 'APPROVED', 'CLOSED'].indexOf(v.status) >= 0) return true;
    }
    if (user.role === 'LAB' || user.role === 'QC') {
      var s = Repo.where('LabSamples', function (x) { return x.visit_id === v.visit_id; });
      if (s.length) return true;
    }
    return false;
  },
  visit: function (user, visitId) {
    var v = Repo.get('Visits', visitId);
    /* Не раскрываем, существует ли запись: одинаковый ответ для «нет» и «нельзя» (AT-03) */
    if (!v || !Auth.canSeeVisit(user, v)) notFound('Выезд');
    return v;
  },
  visitWrite: function (user, visitId) {
    var v = Auth.visit(user, visitId);
    if (user.role === 'SPECIALIST' && v.employee_id !== user.employee_id) notFound('Выезд');
    if (['QC', 'LAB', 'FINANCE'].indexOf(user.role) >= 0) denied('Роль не может изменять результаты выезда');
    return v;
  },

  /* Объекты, которые пользователь вправе видеть */
  visibleSiteIds: function (user) {
    if (Auth.isAdminLike(user) || user.role === 'FINANCE') return null; // null = все
    var ids = {};
    var visits = Store.all('Visits');
    for (var i = 0; i < visits.length; i++) if (Auth.canSeeVisit(user, visits[i])) ids[visits[i].site_id] = true;
    if (user.role === 'LAB') {
      var s = Store.all('LabSamples');
      for (var j = 0; j < s.length; j++) ids[s[j].site_id] = true;
    }
    return ids;
  },

  /* ---------- PIN-режим (если Workspace недоступен) ---------- */
  login: function (email, pin) {
    email = V.str(email).toLowerCase();
    var lockKey = 'lock_' + email, triesKey = 'tries_' + email;
    if (Integr.cacheGet(lockKey)) fail('LOCKED', 'Слишком много попыток. Повторите через 15 минут.');
    var emp = Auth.byEmail(email);
    var ok = emp && V.bool(emp.active) && emp.pin_hash && emp.pin_hash === Integr.hash(email + ':' + V.str(pin));
    if (!ok) {
      var tries = Number(Integr.cacheGet(triesKey) || 0) + 1;
      Integr.cachePut(triesKey, String(tries), 900);
      if (tries >= 5) Integr.cachePut(lockKey, '1', 900);
      fail('AUTH_FAILED', 'Неверный e-mail или PIN-код' + (tries >= 3 && tries < 5 ? '. Осталось попыток: ' + (5 - tries) : ''));
    }
    Integr.cachePut(triesKey, '0', 1);
    var token = uuid();
    Integr.cachePut('sess_' + token, email, 21600);
    return { token: token };
  }
};

/* ---------- Журнал аудита (раздел 14.1 ТЗ) ---------- */
var Audit = {
  log: function (ctx, action, entityType, entityId, oldV, newV) {
    Store.insert('AuditLog', {
      log_id: Repo.newId('AuditLog'),
      timestamp: ctx.now,
      actor_email: ctx.actorEmail || 'system',
      actor_id: ctx.actorId || 'SYSTEM',
      action: action,
      entity_type: entityType,
      entity_id: entityId,
      old_value: shortJson(oldV),
      new_value: shortJson(newV),
      request_id: ctx.requestId || ''
    });
  },

  list: function (ctx, p) {
    var u = ctx.user;
    var rows = Store.all('AuditLog');
    /* Ограниченный доступ по роли (карта окон, раздел 2 инструкции) */
    var allowTypes = null;
    if (u.role === 'QC') allowTypes = ['Reports', 'Visits', 'VisitResults', 'Tasks', 'Documents'];
    if (u.role === 'LAB') allowTypes = ['LabSamples', 'Documents', 'Tasks'];
    if (u.role === 'FINANCE') allowTypes = ['Finance', 'Contracts', 'Clients'];
    if (u.role === 'COORDINATOR') allowTypes = ['Clients', 'Sites', 'Contracts', 'Visits', 'Tasks', 'LabSamples'];
    var q = V.str(p.q).toLowerCase();
    var out = filterBy(rows, function (r) {
      if (allowTypes && allowTypes.indexOf(r.entity_type) < 0) return false;
      if (p.entity_id && r.entity_id !== p.entity_id) return false;
      if (p.entity_type && r.entity_type !== p.entity_type) return false;
      if (p.from && isBefore(r.timestamp, p.from)) return false;
      if (q && (r.entity_id + ' ' + r.action + ' ' + r.actor_email + ' ' + r.new_value).toLowerCase().indexOf(q) < 0) return false;
      return true;
    });
    out = sortBy(out, 'timestamp', true);
    return { total: out.length, rows: out.slice(0, Number(p.limit) || 300) };
  }
};

/* ---------- Ошибки системы ---------- */
var Errors = {
  record: function (ctx, fnName, code, safeMessage, details, entityId) {
    try {
      Store.insert('SystemErrors', {
        error_id: Repo.newId('SystemErrors'), timestamp: ctx.now, function_name: fnName,
        request_id: ctx.requestId || '', error_code: code, safe_message: safeMessage,
        details: String(details || '').slice(0, 2000), entity_id: entityId || '', resolved_status: 'OPEN'
      });
    } catch (e) { /* журнал ошибок не должен ронять операцию */ }
  },
  list: function (ctx, p) {
    var rows = Store.all('SystemErrors');
    if (!p.all) rows = filterBy(rows, function (r) { return r.resolved_status !== 'RESOLVED'; });
    return sortBy(rows, 'timestamp', true).slice(0, 200);
  },
  resolve: function (ctx, p) {
    var e = Store.get('SystemErrors', p.error_id);
    if (!e) notFound('Ошибка');
    Store.update('SystemErrors', p.error_id, { resolved_status: 'RESOLVED', resolved_by: ctx.actorId, resolved_at: ctx.now });
    Audit.log(ctx, 'ERROR_RESOLVE', 'SystemErrors', p.error_id, null, { resolved_status: 'RESOLVED' });
    return { ok: true };
  }
};

/**
 * San.Lab — ClientService.gs
 * Клиенты, объекты, договоры, услуги, сотрудники (раздел 4.1 ТЗ).
 */

function normText(s) { return V.str(s).toLowerCase().replace(/[«»"'.,]/g, '').replace(/\s+/g, ' '); }

var Clients = {
  list: function (ctx, p) {
    var u = ctx.user;
    var siteIds = Auth.visibleSiteIds(u);
    var sites = Store.all('Sites');
    var clientIds = null;
    if (siteIds) {
      clientIds = {};
      for (var i = 0; i < sites.length; i++) if (siteIds[sites[i].site_id]) clientIds[sites[i].client_id] = true;
    }
    var sitesBy = groupBy(sites, 'client_id');
    var emp = indexBy(Store.all('Employees'), 'employee_id');
    var q = normText(p.q);
    var rows = filterBy(Store.all('Clients'), function (c) {
      if (clientIds && !clientIds[c.client_id]) return false;
      if (!p.includeArchived && c.status === 'ARCHIVED') return false;
      if (q && normText(c.legal_name + ' ' + c.inn + ' ' + c.client_id + ' ' + c.contact_person).indexOf(q) < 0) return false;
      return true;
    });
    var fin = Auth.can(u, 'finance.summary') ? Finance.debtByClient() : null;
    return sortBy(rows, 'legal_name').map(function (c) {
      var o = stripSecrets(c);
      o.sites_count = (sitesBy[c.client_id] || []).filter(function (s) { return V.bool(s.active); }).length;
      o.manager_name = emp[c.manager_id] ? emp[c.manager_id].full_name : '';
      if (fin) o.debt = fin[c.client_id] || 0;
      if (u.role === 'SPECIALIST') { o.inn = ''; o.contact_email = ''; o.notes = ''; }
      return o;
    });
  },

  get: function (ctx, p) {
    var u = ctx.user;
    var c = Repo.get('Clients', p.client_id);
    var siteIds = Auth.visibleSiteIds(u);
    var sites = filterBy(Store.all('Sites'), function (s) { return c && s.client_id === c.client_id && (!siteIds || siteIds[s.site_id]); });
    if (!c || (siteIds && !sites.length)) notFound('Клиент');
    var out = { client: stripSecrets(c), sites: sites, contracts: [], visits: [], finance: null, documents: [] };
    if (u.role !== 'SPECIALIST') out.contracts = Repo.where('Contracts', function (x) { return x.client_id === c.client_id; });
    var vis = Visits.list(ctx, { client_id: c.client_id, limit: 50 });
    out.visits = vis.rows;
    if (Auth.can(u, 'finance.summary')) out.finance = Finance.clientCard(c.client_id);
